def countStrings(S):
    n = len(S)
    last = [-1] * 26
    result = 0

    for i in range(n):
        for c in range(ord('a'), ord('z') + 1):
            if last[c - ord('a')] != -1:
                result += i - last[c - ord('a')] - 1
        last[ord(S[i]) - ord('a')] = i

    return result + (n * (n - 1)) // 2 - (n - 1)
